package kernel

import (
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sync"
	"syscall"

	"github.com/james-nesbitt/alloy/api"
)

// SharedBuffer represents a memory-mapped buffer accessible by multiple plugins.
type SharedBuffer struct {
	ID           string
	Name         string
	Path         string
	Size         int
	Data         []byte
	File         *os.File
	LastModified int64
	Version      int
	History      []api.BufferChange
	mu           sync.RWMutex
	onUpdate     []func(id string, offset int, length int)
	manager      *BufferManager // Reference to parent for event broadcasting
}

// Satisfy SharedBuffer interface for api.SharedBuffer
func (b *SharedBuffer) GetID() string          { return b.ID }
func (b *SharedBuffer) GetName() string        { return b.Name }
func (b *SharedBuffer) GetData() []byte        { return b.Data }
func (b *SharedBuffer) GetSize() int           { return b.Size }
func (b *SharedBuffer) Lock()                  { b.mu.Lock() }
func (b *SharedBuffer) Unlock()                { b.mu.Unlock() }
func (b *SharedBuffer) GetVersion() int        { return b.Version }
func (b *SharedBuffer) GetLastModified() int64 { return b.LastModified }

func (b *SharedBuffer) OnUpdate(callback func(id string, offset int, length int)) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.onUpdate = append(b.onUpdate, callback)
}

func (b *SharedBuffer) triggerUpdate(offset, length int) {
	// Assumes lock is already held if called from internal methods,
	// but we should be careful.
	// To be safe, we'll copy the slice under lock and then execute outside.
	callbacks := make([]func(id string, offset int, length int), len(b.onUpdate))
	copy(callbacks, b.onUpdate)

	go func() {
		for _, cb := range callbacks {
			cb(b.ID, offset, length)
		}
	}()
}

// Resize increases the size of the shared buffer.
func (b *SharedBuffer) Resize(newSize int) error {
	b.mu.Lock()
	defer b.mu.Unlock()
	err := b.resize(newSize)
	if err == nil {
		b.triggerUpdate(0, newSize)
	}
	return err
}

func (b *SharedBuffer) resize(newSize int) error {
	if newSize <= b.Size {
		return nil
	}

	// Unmap old data
	if b.Data != nil {
		if err := syscall.Munmap(b.Data); err != nil {
			return fmt.Errorf("failed to munmap old data: %w", err)
		}
	}

	// Truncate file
	if err := b.File.Truncate(int64(newSize)); err != nil {
		return fmt.Errorf("failed to truncate file: %w", err)
	}

	// Mmap new data
	data, err := syscall.Mmap(int(b.File.Fd()), 0, newSize, syscall.PROT_READ|syscall.PROT_WRITE, syscall.MAP_SHARED)
	if err != nil {
		return fmt.Errorf("failed to mmap resized file: %w", err)
	}

	b.Data = data
	b.Size = newSize
	return nil
}

// ApplyChange updates the buffer data and tracks the history for conflict resolution.
func (b *SharedBuffer) ApplyChange(change api.BufferChange) error {
	b.mu.Lock()
	defer b.mu.Unlock()

	// Conflict Resolution Phase 12:
	// A change is "valid" even if stale if it doesn't overlap with any intermediate changes.
	if change.Version < b.Version {
		for i := len(b.History) - 1; i >= 0; i-- {
			hist := b.History[i]
			if hist.Version < change.Version {
				// History is sorted by version, we can stop once we're behind the incoming change.
				break
			}

			// Intersection check
			if (change.Offset < hist.Offset+len(hist.Data)) && (change.Offset+len(change.Data) > hist.Offset) {
				// We have a direct overlap. Use LWW (Last Write Wins) based on timestamp.
				// If the incoming change is physically older than a change we already applied to this region, we reject it.
				if change.Timestamp <= hist.Timestamp {
					return fmt.Errorf("buffer conflict: stale change (v%d) at offset %d overlaps with newer version (v%d)", change.Version, change.Offset, hist.Version)
				}
			}
		}
	}

	if change.Offset+len(change.Data) > b.Size {
		// Auto-resize for incoming changes
		if err := b.resize(change.Offset + len(change.Data) + 1024); err != nil {
			return err
		}
	}

	copy(b.Data[change.Offset:], change.Data)
	b.Version++
	b.LastModified = change.Timestamp

	// Track in history (Limited to last 100 changes for "lite" model)
	b.History = append(b.History, change)
	if len(b.History) > 100 {
		b.History = b.History[1:]
	}

	// Trigger callbacks and broadcast event for headless sync (Phase 12)
	b.triggerUpdate(change.Offset, len(change.Data))

	if b.manager != nil && b.manager.events != nil {
		eventData, _ := json.Marshal(map[string]any{
			"id":      b.ID,
			"offset":  change.Offset,
			"length":  len(change.Data),
			"version": b.Version,
			"actor":   change.Actor,
		})
		b.manager.events.Publish(context.Background(), "buffer:updated", "kernel", eventData)
	}

	return nil
}

// VisualIntent broadcasts a virtual cursor or highlight for this buffer (Phase 12)
func (b *SharedBuffer) VisualIntent(intent api.VisualIntent) error {
	if b.manager != nil && b.manager.events != nil {
		intent.BufferID = b.ID
		eventData, _ := json.Marshal(intent)
		b.manager.events.Publish(context.Background(), "visual:intent", "kernel", eventData)
	}
	return nil
}

// BufferManager handles the lifecycle of shared memory-mapped buffers.
type BufferManager struct {
	logger  *slog.Logger
	dataDir string
	buffers map[string]*SharedBuffer
	mu      sync.RWMutex
