			if hist.Version < change.Version {
				// History is sorted by version, we can stop once we're behind the incoming change.
				break
			}

			// Intersection check
			if (change.Offset < hist.Offset+len(hist.Data)) && (change.Offset+len(change.Data) > hist.Offset) {
				// We have a direct overlap. Use LWW (Last Write Wins) based on timestamp.
				// If the incoming change is physically older than a change we already applied to this region, we reject it.
				if change.Timestamp <= hist.Timestamp {
					return fmt.Errorf("buffer conflict: stale change (v%d) at offset %d overlaps with newer version (v%d)", change.Version, change.Offset, hist.Version)
				}
			}
		}
	}

	if change.Offset+len(change.Data) > b.Size {
		// Auto-resize for incoming changes
		if err := b.resize(change.Offset + len(change.Data) + 1024); err != nil {
			return err
		}
	}

	copy(b.Data[change.Offset:], change.Data)
	b.Version++
	b.LastModified = change.Timestamp

	// Track in history (Limited to last 100 changes for "lite" model)
	b.History = append(b.History, change)
	if len(b.History) > 100 {
		b.History = b.History[1:]
	}

	// Trigger callbacks and broadcast event for headless sync (Phase 12)
	b.triggerUpdate(change.Offset, len(change.Data))

	if b.manager != nil && b.manager.events != nil {
		eventData, _ := json.Marshal(map[string]any{
			"id":      b.ID,
			"offset":  change.Offset,
			"length":  len(change.Data),
			"version": b.Version,
			"actor":   change.Actor,
		})
		b.manager.events.Publish(context.Background(), "buffer:updated", "kernel", eventData)
	}

	return nil
}

// VisualIntent broadcasts a virtual cursor or highlight for this buffer (Phase 12)
func (b *SharedBuffer) VisualIntent(intent api.VisualIntent) error {
	if b.manager != nil && b.manager.events != nil {
		intent.BufferID = b.ID
		eventData, _ := json.Marshal(intent)
		b.manager.events.Publish(context.Background(), "visual:intent", "kernel", eventData)
	}
	return nil
}

// BufferManager handles the lifecycle of shared memory-mapped buffers.
type BufferManager struct {
	logger  *slog.Logger
	dataDir string
	buffers map[string]*SharedBuffer
	mu      sync.RWMutex
	events  *EventManager
}

// NewBufferManager creates a new BufferManager.
func NewBufferManager(logger *slog.Logger, dataDir string) *BufferManager {
	return &BufferManager{
		logger:  logger,
		dataDir: dataDir,
		buffers: make(map[string]*SharedBuffer),
	}
}

// SetEventManager attaches an EventManager for broadcasting (Phase 12)
func (bm *BufferManager) SetEventManager(e *EventManager) {
	bm.mu.Lock()
	defer bm.mu.Unlock()
	bm.events = e
}

// CreateBuffer creates or opens a memory-mapped buffer.
func (bm *BufferManager) CreateBuffer(id, name string, initialSize int) (api.SharedBuffer, error) {
	bm.mu.Lock()
	defer bm.mu.Unlock()

	if b, ok := bm.buffers[id]; ok {
		return b, nil
	}

	path := filepath.Join(bm.dataDir, "buffers", id+".data")
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		return nil, fmt.Errorf("failed to create buffers dir: %w", err)
	}

	file, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0644)
	if err != nil {
		return nil, fmt.Errorf("failed to open buffer file: %w", err)
	}

	info, err := file.Stat()
	if err != nil {
		file.Close()
		return nil, fmt.Errorf("failed to stat buffer file: %w", err)
	}

	if initialSize <= 0 {
		initialSize = 1024 * 64 // Default to 64KB
	}

	if info.Size() < int64(initialSize) {
		if err := file.Truncate(int64(initialSize)); err != nil {
			file.Close()
			return nil, fmt.Errorf("failed to truncate buffer file: %w", err)
		}
	} else {
		initialSize = int(info.Size())
	}

	data, err := syscall.Mmap(int(file.Fd()), 0, initialSize, syscall.PROT_READ|syscall.PROT_WRITE, syscall.MAP_SHARED)
	if err != nil {
		file.Close()
		return nil, fmt.Errorf("failed to mmap buffer file: %w", err)
	}

	b := &SharedBuffer{
		ID:      id,
		Name:    name,
		Path:    path,
		Size:    initialSize,
		Data:    data,
		File:    file,
		manager: bm,
	}

	bm.buffers[id] = b
	bm.logger.Info("created shared mmap buffer", "id", id, "size", initialSize, "path", path)
	return b, nil
}

// GetBuffer retrieves a shared buffer by ID.
func (bm *BufferManager) GetBuffer(id string) (api.SharedBuffer, bool) {
	bm.mu.RLock()
	defer bm.mu.RUnlock()
	b, ok := bm.buffers[id]
	if !ok {
		return nil, false
	}
	return b, ok
}

// Write (Appends or Overwrites data)
func (b *SharedBuffer) Write(offset int, content []byte) error {
	b.mu.Lock()
	defer b.mu.Unlock()

	if offset+len(content) > b.Size {
		return fmt.Errorf("buffer overflow: resize required")
	}

	copy(b.Data[offset:], content)
	b.Version++
	b.triggerUpdate(offset, len(content))
	return nil
}

// Close closes all buffers.
func (bm *BufferManager) Close() error {
	bm.mu.Lock()
	defer bm.mu.Unlock()

	for _, b := range bm.buffers {
		_ = syscall.Munmap(b.Data)
		_ = b.File.Close()
	}
	return nil
}

